SELECT toJSONString(tuple((SELECT groupArray(tuple(name,sorting_key,partition_key,total_rows)) FROM system.tables WHERE database='system' AND match(name,'^asynchronous_metric_log')), (SELECT groupArray(tuple(table,name,type,comment)) FROM system.columns WHERE database='system' AND table='asynchronous_metric_log'), (SELECT groupArray(tuple(metric,value,description)) FROM system.asynchronous_metrics WHERE match(metric,'Memory|CacheBytes') LIMIT 100))) AS payload LIMIT 1 SETTINGS max_threads=2,max_execution_time=15,timeout_before_checking_execution_speed=0,max_rows_to_read=100000;
